  function cesCanvasHasVisibleContent(canvas){
    try{
      if(!canvas || !canvas.width || !canvas.height) return false;
      var ctx = canvas.getContext('2d', {willReadFrequently:true});
      if(!ctx) return true;
      var cols = 28, rows = 20, visible = 0, dark = 0, colorful = 0;
      for(var gy=0; gy<rows; gy++){
        for(var gx=0; gx<cols; gx++){
          var x = Math.min(canvas.width-1, Math.max(0, Math.floor((gx+.5)*canvas.width/cols)));
          var y = Math.min(canvas.height-1, Math.max(0, Math.floor((gy+.5)*canvas.height/rows)));
          var px = ctx.getImageData(x,y,1,1).data;
          var r=px[0], g=px[1], b=px[2], a=px[3];
          if(a < 8) continue;
          var nearWhite = r>239 && g>242 && b>246;
          var nearAppBg = Math.abs(r-246)<9 && Math.abs(g-249)<9 && Math.abs(b-253)<9;
          if(!nearWhite && !nearAppBg) visible++;
          if(r<190 || g<190 || b<190) dark++;
          if(Math.max(r,g,b)-Math.min(r,g,b)>22) colorful++;
        }
      }
      return visible >= 8 && (dark >= 3 || colorful >= 3);
    }catch(ignore){
      /* A CORS-tainted canvas can still be valid for jsPDF in some browsers. */
      return true;
    }
  }

  function cesGetVisibleRectForCapture(el, stopAt){
    var r=el.getBoundingClientRect();
    var left=Math.max(0,r.left), top=Math.max(0,r.top);
    var right=Math.min(window.innerWidth || document.documentElement.clientWidth || r.right,r.right);
    var bottom=Math.min(window.innerHeight || document.documentElement.clientHeight || r.bottom,r.bottom);
    var parent=el.parentElement;
    while(parent && parent!==document.body && parent!==document.documentElement){
      try{
        var st=window.getComputedStyle(parent);
        var pr=parent.getBoundingClientRect();
        var clipsX=/(auto|scroll|hidden|clip)/i.test(st.overflowX || st.overflow || '');
        var clipsY=/(auto|scroll|hidden|clip)/i.test(st.overflowY || st.overflow || '');
        if(clipsX){ left=Math.max(left,pr.left); right=Math.min(right,pr.right); }
        if(clipsY){ top=Math.max(top,pr.top); bottom=Math.min(bottom,pr.bottom); }
      }catch(ignore){}
      if(parent===stopAt) break;
      parent=parent.parentElement;
    }
    return {
      left:left,
      top:top,
      right:right,
      bottom:bottom,
      width:Math.max(0,right-left),
      height:Math.max(0,bottom-top)
    };
  }

  function cesCropCanvas(sourceCanvas,sx,sy,sw,sh){
    sx=Math.max(0,Math.floor(sx));
    sy=Math.max(0,Math.floor(sy));
    sw=Math.max(1,Math.min(sourceCanvas.width-sx,Math.ceil(sw)));
    sh=Math.max(1,Math.min(sourceCanvas.height-sy,Math.ceil(sh)));
    var out=document.createElement('canvas');
    out.width=sw;
    out.height=sh;
    var ctx=out.getContext('2d');
    ctx.fillStyle='#f6f9fd';
    ctx.fillRect(0,0,sw,sh);
    ctx.drawImage(sourceCanvas,sx,sy,sw,sh,0,0,sw,sh);
    return out;
  }

  function cesCopyCurrentFormState(sourceRoot, cloneRoot){
    var sourceFields=sourceRoot.querySelectorAll('input,select,textarea');
    var cloneFields=cloneRoot.querySelectorAll('input,select,textarea');
    for(var i=0;i<sourceFields.length && i<cloneFields.length;i++){
      var source=sourceFields[i], clone=cloneFields[i];
      try{
        if(source.tagName==='SELECT'){
          clone.value=source.value;
          for(var o=0;o<clone.options.length;o++) clone.options[o].selected=(clone.options[o].value===source.value);
        }else if(source.type==='checkbox' || source.type==='radio'){
          clone.checked=source.checked;
          if(source.checked) clone.setAttribute('checked','checked'); else clone.removeAttribute('checked');
        }else{
          clone.value=source.value;
          clone.setAttribute('value',source.value);
          if(clone.tagName==='TEXTAREA') clone.textContent=source.value;
        }
      }catch(ignore){}
    }
  }

  function cesFreezeServiceCanvases(sourceRoot,cloneRoot){
    var sourceCanvases=sourceRoot.querySelectorAll('canvas');
    var cloneCanvases=cloneRoot.querySelectorAll('canvas');
    for(var i=0;i<sourceCanvases.length && i<cloneCanvases.length;i++){
      var sourceCanvas=sourceCanvases[i], cloneCanvas=cloneCanvases[i];
      try{
        var png=sourceCanvas.toDataURL('image/png',1);
        var image=document.createElement('img');
        image.src=png;
        image.alt=sourceCanvas.getAttribute('aria-label') || sourceCanvas.id || 'Dashboard chart';
        image.className=(sourceCanvas.className || '')+' ces-service-print-chart-v12';
        image.style.display='block';
        image.style.width='100%';
        image.style.height='100%';
        image.style.maxWidth='100%';
        image.style.maxHeight='100%';
        image.style.objectFit='contain';
        image.style.objectPosition='center';
        image.setAttribute('width',String(Math.max(1,sourceCanvas.offsetWidth || sourceCanvas.width || 1)));
        image.setAttribute('height',String(Math.max(1,sourceCanvas.offsetHeight || sourceCanvas.height || 1)));
        cloneCanvas.parentNode.replaceChild(image,cloneCanvas);
      }catch(err){
        console.warn('[CES Final] could not freeze canvas for print',sourceCanvas.id || i,err);
      }
    }
  }

