  function cesWaitForPrintFrame(frame){
    return new Promise(function(resolve){
      var doc=frame.contentDocument;
      var finished=false;
      var timer=setTimeout(done,8000);
      function done(){
        if(finished) return;
        finished=true;
        clearTimeout(timer);
        try{
          var win=frame.contentWindow;
          win.requestAnimationFrame(function(){ win.requestAnimationFrame(function(){ setTimeout(resolve,120); }); });
        }catch(ignore){ resolve(); }
      }

      var waits=[];
      var links=doc.querySelectorAll('link[rel="stylesheet"]');
      for(var i=0;i<links.length;i++){
        waits.push(new Promise(function(res){
          var settled=false;
          function finish(){ if(settled) return; settled=true; res(); }
          this.addEventListener('load',finish,{once:true});
          this.addEventListener('error',finish,{once:true});
          setTimeout(finish,2500);
        }.bind(links[i])));
      }
      var images=doc.images || [];
      for(var j=0;j<images.length;j++){
        if(images[j].complete) continue;
        waits.push(new Promise(function(res){
          var settled=false;
          function finish(){ if(settled) return; settled=true; res(); }
          this.addEventListener('load',finish,{once:true});
          this.addEventListener('error',finish,{once:true});
          setTimeout(finish,2500);
        }.bind(images[j])));
      }
      if(doc.fonts && doc.fonts.ready) waits.push(Promise.resolve(doc.fonts.ready).catch(function(){}));
      Promise.all(waits).then(done).catch(done);
      if(!waits.length) done();
    });
  }

