  function calendarNormalizeSourceTeam_(value){
    var t = text(value).trim().toUpperCase();
    if(t === 'MANAGEMENT' || t === 'MNG') return 'MGT';
    if(t.indexOf('MED') >= 0) return 'MED';
    if(t.indexOf('LAB') >= 0) return 'LAB';
    if(t.indexOf('TES') >= 0 || t.indexOf('TECHNICAL') >= 0) return 'TES';
    if(t.indexOf('ENV') >= 0 || t.indexOf('ENVIRONMENT') >= 0) return 'ENV';
    if(t.indexOf('EHS') >= 0 || t.indexOf('HEALTH') >= 0) return 'EHS';
    if(t.indexOf('MGT') >= 0 || t.indexOf('MANAG') >= 0) return 'MGT';
    return t;
  }
  function calendarSourceTeam_(item){
    var calendarId = text(item && item.calendarId).trim().toLowerCase();
    if(calendarId === 'chiraphat.env@gmail.com') return 'ENV';
    if(calendarId === 'natkanok.8942@gmail.com') return 'EHS';
    if(calendarId === 'cescalmedteam@gmail.com') return 'MED';
    if(calendarId === 'nhealthcallab@gmail.com') return 'LAB';
    if(calendarId === 'technicalsupport.tes@gmail.com') return 'TES';
    if(calendarId === 'cesmanagement2026@gmail.com') return 'MGT';
    return calendarNormalizeSourceTeam_(item && item.team);
  }
  function calendarCapacityTeam_(item, sourceTeam){
    return sourceTeam || calendarSourceTeam_(item);
  }
  function calendarUiMatches_(current, sourceTeam){
    return current === 'ALL' || current === sourceTeam;
  }
  function calendarDate_(value){
    var raw = text(value).trim();
    var p = raw.split('/');
    if(p.length >= 3) return new Date(Number(p[2]), Number(p[1])-1, Number(p[0]));
    var d = new Date(raw);
    return d;
  }

  function processCalendarDataFinal(data, targetM, targetY){
    ensureCalendarTeamUi();
    data = Array.isArray(data) ? data : [];
    var current = (typeof currentService !== 'undefined') ? currentService : 'ALL';
    var teamKeys = ['MED','LAB','EHS','ENV','TES','MGT'];
    var sets = {}, man = {};
    teamKeys.forEach(function(t){ sets[t]=new Set(); man[t]=0; });
    var jobs = [], leave = [], other = [];
    data.forEach(function(item){
      var itemM = parseInt(item.month,10), itemY = parseInt(item.year,10);
      if(itemM !== targetM || itemY !== targetY) return;
      var title = text(item.title);
      var sourceTeam = calendarSourceTeam_(item);
      if(teamKeys.indexOf(sourceTeam) < 0) return;
      var capacityTeam = calendarCapacityTeam_(item, sourceTeam);
      var isLeave = (typeof checkIsLeaveEvent === 'function') ? checkIsLeaveEvent(title) : /leave|off|ลา|หยุด|ป่วย/i.test(title);
      if(isLeave){ if(calendarUiMatches_(current, sourceTeam)) leave.push(Object.assign({}, item, {team:sourceTeam})); return; }
      var isOther = (typeof checkIsOtherCalendarActivity === 'function') ? checkIsOtherCalendarActivity(title) : /ส่ง\s*cal|ส่งสอบเทียบ|ส่งเครื่อง|ยืมเครื่อง|(?:^|\s)ยืม(?:\s|$)/i.test(title);
      if(isOther){ if(calendarUiMatches_(current, sourceTeam)) other.push(Object.assign({}, item, {team:sourceTeam})); return; }
      if(!title) return;
      // Count every scheduled non-leave work day, including weekend work.
      if(man.hasOwnProperty(capacityTeam)) man[capacityTeam] += 1;
      var key = item.uniqueKey || [sourceTeam,item.date,title].join('|');
      sets[sourceTeam].add(key);
      if(calendarUiMatches_(current, sourceTeam)) jobs.push(Object.assign({}, item, {team:sourceTeam, capacityTeam:capacityTeam}));
    });
    var total = ['MED','LAB','EHS','ENV','TES'].reduce(function(a,t){ return a + sets[t].size; }, 0);
    var el;
    if((el=qs('#stat-total'))) el.innerText = total;
    ['MED','LAB','EHS','ENV','TES'].forEach(function(t){ var node=qs('#stat-'+t.toLowerCase()); if(node) node.innerText=sets[t].size; });
    var weekdays = (typeof getWeekdaysInMonth === 'function') ? getWeekdaysInMonth(targetM, targetY) : 0;
    if((el=qs('#capacity-days-display'))) el.innerText = weekdays + ' Weekdays';
    renderCapacityBarsFinal(man, weekdays);
    if(typeof renderJobTable === 'function') renderJobTable(jobs);
    if(typeof renderLeaveList === 'function') renderLeaveList(leave);
    if(typeof renderCalendarOtherList === 'function') renderCalendarOtherList(other);
  }
  function renderCapacityBarsFinal(manDays, weekdays){
    var container = qs('#capacity-dashboard-grid'); if(!container) return;
    var cfg = (typeof globalConfig !== 'undefined' && globalConfig) ? globalConfig : {};
    var limits = {
      MED:num(cfg.CAPACITY_MED || cfg.MED || 12)||12,
      LAB:num(cfg.CAPACITY_LAB || cfg.LAB || 3)||3,
      EHS:num(cfg.CAPACITY_EHS || cfg.EHS || 3)||3,
      ENV:num(cfg.CAPACITY_ENV || cfg.ENV || cfg.CAPACITY_EHS || 3)||3,
      TES:num(cfg.CAPACITY_TES || cfg.TES || 4)||4
    };
    var palette = {MED:'#0057B8',LAB:'#0891B2',EHS:'#0B8043',ENV:'#33B679',TES:'#D97706'};
    container.innerHTML = ['MED','LAB','EHS','ENV','TES'].map(function(t){
      var val = num(manDays && manDays[t]);
      var target = weekdays * limits[t];
      var p = target ? Math.round(val / target * 100) : 0;
      var over = p > 100;
      var color = over ? '#E4002B' : palette[t];
      return `<div class="bg-white rounded-xl p-4 shadow-sm border border-[#D8E6F7] relative overflow-hidden group hover:shadow-md transition-all">
        <div class="flex justify-between items-end mb-2"><div><span class="text-[10px] font-black text-slate-400 uppercase tracking-widest">${t} Team</span><div class="text-xs text-slate-500 font-bold">Limit: ${limits[t]}/day</div></div><div class="text-2xl font-black" style="color:${color}">${p}%</div></div>
        <div class="w-full bg-slate-100 h-2.5 rounded-full overflow-hidden mb-2"><div style="width:${Math.min(p,100)}%;background:${color}" class="h-full rounded-full transition-all duration-1000"></div></div>
        <div class="flex justify-between items-center text-[10px] font-bold text-slate-400 border-t border-slate-50 pt-2"><span>Actual: <b class="text-slate-600">${val}</b></span><span>Capacity: <b class="text-slate-600">${target}</b> MD</span></div>
      </div>`;
    }).join('');
  }
  try { if(typeof window.processCalendarData !== 'function') window.processCalendarData = processCalendarDataFinal; if(typeof window.renderCapacityBars !== 'function') window.renderCapacityBars = renderCapacityBarsFinal; } catch(e) {}

